<include file="Public:header"/>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('Mall/mall_goods_list')}">全部商品</a>					<a href="{pigcms{:U('Mall/mall_seckill_list')}" class="on">{pigcms{$config.seckill_alias_name|default='限时购'}商品</a>					<a href="{pigcms{:U('Mall/mall_group_list')}">拼团商品</a>					<a href="{pigcms{:U('Mall/mall_cut_list')}">砍价商品</a>				</ul>			</div>			<table class="search_table" width="100%">				<tr>					<td>						<form action="{pigcms{:U('Mall/mall_seckill_list')}" method="get">							<input type="hidden" name="c" value="Mall"/>							<input type="hidden" name="a" value="mall_seckill_list"/>							<input type="hidden" name="mer_id" value="{pigcms{$_GET.mer_id}"/>							筛选: <input type="text" name="keyword" class="input-text" value="{pigcms{$_GET['keyword']}"/>							<select name="searchtype">								<option value="name" <if condition="$_GET['searchtype'] eq 'name'">selected="selected"</if>>商品名称</option>								<option value="goods_id" <if condition="$_GET['searchtype'] eq 'goods_id'">selected="selected"</if>>商品编号</option>								<option value="number" <if condition="$_GET['searchtype'] eq 'number'">selected="selected"</if>>商品条形码</option>							</select>							&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;							首页优选：							<select name='is_preference'>								<option value="-1" <if condition="$_GET['is_preference'] EQ -1">selected</if>>全部</option>								<option value="1" <if condition="$_GET['is_preference'] EQ 1">selected</if>>优选商品</option>								<option value="0" <if condition="$_GET['is_preference'] EQ 0 && isset($_GET['is_preference'])">selected</if> >非优选商品</option>							</select>							&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;							<input type="submit" value="查询" class="button"/>														<if condition="$now_groupwxapp_category">								<input type="button" value="添加优选商品" class="button" onclick="window.top.artiframe('{pigcms{:U('Groupwxapp/product_add',$_GET)}','添加优选商品 - {pigcms{$now_groupwxapp_category.cat_name}',600,400,true,false,false,addbtn,'edit',true);" style="float:right;margin-right:100px;"/>							</if>						</form>					</td>				</tr>			</table>			<form name="myform" id="myform" action="" method="post">				<div class="table-list">					<style>					.table-list td{line-height:22px;padding-top:5px;padding-bottom:5px;}					</style>					<table width="100%" cellspacing="0">						<thead>							<tr>								<th>编号</th>								<th>推荐排序值</th>								<th>商品名称</th>								<th>商家名称</th>								<th>店铺名称</th>														<th>原价/{pigcms{$config['Currency_txt']}</th>								<!-- <th>现价/{pigcms{$config['Currency_txt']}</th> -->								<th>限时价/{pigcms{$config['Currency_txt']}</th>								<th>活动开始时间</th>								<th>活动结束时间</th>								<th>操作</th>							</tr>						</thead>						<tbody>							<volist name="list" id='vo'>								<tr>									<td>{pigcms{$vo.goods_id}</td>									<td>{pigcms{$vo.promote_sort|default=0}</td>									<td>{pigcms{$vo.name}</td>									<td>{pigcms{$vo.mer_name}</td>									<td>{pigcms{$vo.store_name}</td>																		<td>{pigcms{$vo.old_price}</td>									<!-- <td>{pigcms{$vo.price}</td> -->									<td>{pigcms{$vo.limit_price}</td>											<td>{pigcms{$vo.start_date}</td>											<td>{pigcms{$vo.end_date}</td>									<td>										<a href="javascript:void(0);" onclick="edit('{pigcms{$vo.promote_id}',{pigcms{$vo.goods_id},{pigcms{$vo.goods_id},1);">首页推荐设置</a>|										<a href="{pigcms{:U('Mall/goods_edit',array('mer_id'=>$vo['mer_id'],'goods_id'=>$vo['goods_id']))}">编辑</a>										|										<if condition="$vo.is_preference eq 1">											<a href="javascript:void(0);" onclick="set_perfence({pigcms{$vo.goods_id});">取消优选</a>											<else/>											<a href="javascript:void(0);" onclick="set_perfence({pigcms{$vo.goods_id});">设为优选</a>										</if>									</td>								</tr>							</volist>							<empty name='list'>								<tr><td class='textcenter' colspan='30'>暂无限时购商品</td></tr>							<else/>								<tr><td class="textcenter pagebar" colspan="30">{pigcms{$pagebar}</td></tr>							</empty>													</tbody>					</table>				</div>			</form>		</div><script type="text/javascript">var url="{pigcms{:U('Mall/adver_goods_edit')}";function edit(id,goods_id,act_id,type){	url+='&id='+id;	url+='&goods_id='+goods_id;	url+='&act_id='+act_id;	url+='&type='+type;	window.top.artiframe(url,'推荐到首页',480,260,true,false,false,editbtn,'edit',true);}function set_perfence(goods_id){	$.post('{pigcms{:U("Mall/set_perfence")}',{'goods_id':goods_id},function(res){		if(res.errorcode=='1'){			alert(res.info);		}else{			alert(res.info);			window.location.reload();		}	},'json');}</script><include file="Public:footer"/>